I've added V7, V8 and V9 in `validators_later.py`, with tests in `test_validators_later.py`. I haven't run any of it.

<file path="validators_later.py">
"""Later validators over depot harness outputs, in the same form as ``validators.py``.

Each validator subclasses ``Check`` and returns ``(passed, measured)``. ``measured`` is
``None`` when nothing was actually compared, and counts are included so a clean result
is still non-empty.
"""
from __future__ import annotations

from checks_base import Check

# The spec gives no bounds for supplier reliability; assumed inclusive 0..100.
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


class V7(Check):
    """Every warehouse's capacity was respected across runs."""

    name = "V7"

    def check(self, entries):
        entries = list(entries)
        over = [e["wh"] for e in entries if e["max_units"] > e["capacity"]]
        return (not over), {
            "entries": len(entries),
            "over_capacity": len(over),
            "over_capacity_whs": sorted(set(over)),
        }


class V8(Check):
    """All expiries were notified."""

    name = "V8"

    def check(self, entries):
        compared = 0
        missing = []
        for e in entries:
            notified = {tuple(n) for n in (e["notified"] or [])}
            for x in e["expired"] or []:
                compared += 1
                if tuple(x) not in notified:
                    missing.append(tuple(x))
        if compared == 0:
            return False, None  # no expiries occurred: nothing was compared
        return (not missing), {
            "expiries": compared,
            "unnotified": len(missing),
            "unnotified_items": missing,
        }


class V9(Check):
    """Every supplier's reliability stayed in range."""

    name = "V9"

    def check(self, entries):
        entries = list(entries)
        bad = [
            e["supplier"]
            for e in entries
            if not (RELIABILITY_MIN <= e["reliability"] <= RELIABILITY_MAX)
        ]
        return (not bad), {
            "entries": len(entries),
            "out_of_range": len(bad),
            "out_of_range_suppliers": sorted(set(bad)),
        }
</file>

<file path="test_validators_later.py">
import unittest

from validators_later import V7, V8, V9


class TestV7(unittest.TestCase):
    def test_pass(self):
        r = V7().run([{"wh": "A", "capacity": 10, "max_units": 10}])
        self.assertTrue(r.passed)

    def test_fail(self):
        r = V7().run([{"wh": "A", "capacity": 10, "max_units": 11}])
        self.assertFalse(r.passed)
        self.assertEqual(r.measured["over_capacity_whs"], ["A"])

    def test_empty(self):
        self.assertFalse(V7().run([]).passed)


class TestV8(unittest.TestCase):
    def test_pass(self):
        e = {"expired": [["s", "A", 2]], "notified": [["s", "A", 2]]}
        self.assertTrue(V8().run([e]).passed)

    def test_missing(self):
        e = {"expired": [["s", "A", 2]], "notified": []}
        r = V8().run([e])
        self.assertFalse(r.passed)
        self.assertEqual(r.measured["unnotified"], 1)

    def test_no_expiries_is_not_a_pass(self):
        r = V8().run([{"expired": [], "notified": [["s", "A", 1]]}])
        self.assertFalse(r.passed)


class TestV9(unittest.TestCase):
    def test_pass(self):
        r = V9().run([{"supplier": "x", "reliability": 0},
                      {"supplier": "y", "reliability": 100}])
        self.assertTrue(r.passed)

    def test_fail(self):
        r = V9().run([{"supplier": "x", "reliability": 101}])
        self.assertFalse(r.passed)
        self.assertEqual(r.measured["out_of_range_suppliers"], ["x"])

    def test_empty(self):
        self.assertFalse(V9().run([]).passed)


if __name__ == "__main__":
    unittest.main()
</file>

<notes>
- V9: the spec doesn't define "in range", so I assumed an inclusive 0..100 range. The bounds are the constants `RELIABILITY_MIN` and `RELIABILITY_MAX`; please confirm or correct them.
- V7: each entry is checked on its own (`max_units <= capacity`), so a warehouse that appears in several entries is checked in each one.
- V8: an expiry counts as notified if its `(sku, wh, qty)` appears in the same entry's `notified` list. Quantities aren't counted, so a duplicate expiry matched by a single notification still passes. If no entry contains any expiry, V8 returns `(False, None)`, like V3, so it reports "nothing measured" rather than passing on nothing.
</notes>
